package dev.detekt.core.settings

import dev.detekt.tooling.api.spec.ExtensionsSpec
import org.jetbrains.kotlin.utils.closeQuietly
import java.io.Closeable
import java.net.URLClassLoader
import kotlin.io.path.exists
import kotlin.io.path.extension

interface ClassloaderAware {

    val pluginLoader: ClassLoader

    fun closeLoaderIfNeeded()
}

class ExtensionFacade(private val plugins: ExtensionsSpec.Plugins?) :
    AutoCloseable,
    Closeable,
    ClassloaderAware {

    init {
        plugins?.paths?.forEach {
            require(it.exists()) { "Given plugin ‘$it’ does not exist." }
            require(it.extension == "jar") { "Given plugin ‘$it’ is not a JAR." }
        }
    }

    /**
     * Shared class loader used to load services from plugin jars.
     */
    override val pluginLoader: ClassLoader by lazy {
        when {
            plugins?.loader != null -> checkNotNull(plugins.loader)

            plugins?.paths != null -> {
                val pluginUrls = checkNotNull(plugins.paths)
                    .map { it.toUri().toURL() }
                    .toTypedArray()
                URLClassLoader(pluginUrls, javaClass.classLoader)
            }

            else -> javaClass.classLoader
        }
    }

    override fun close() {
        closeLoaderIfNeeded()
    }

    override fun closeLoaderIfNeeded() {
        if (plugins?.paths != null) {
            // we created a classloader and need to close it
            closeQuietly(pluginLoader as? URLClassLoader)
        }
    }
}
package dev.detekt.core.rules

import dev.detekt.api.RuleSetProvider
import dev.detekt.api.internal.DefaultRuleSetProvider
import dev.detekt.core.ProcessingSettings
import dev.detekt.core.extensions.LIST_ITEM_SPACING
import dev.detekt.core.extractRuleName
import dev.detekt.tooling.api.spec.RulesSpec
import java.util.ServiceLoader

fun ProcessingSettings.createRuleProviders(): List<RuleSetProvider> {
    val ruleSetProviders = ServiceLoader.load(RuleSetProvider::class.java, pluginLoader)
        .filterNot { it.ruleSetId.value in spec.extensionsSpec.disabledExtensions }

    return when (val runPolicy = spec.rulesSpec.runPolicy) {
        RulesSpec.RunPolicy.NoRestrictions -> ruleSetProviders

        RulesSpec.RunPolicy.DisableDefaultRuleSets ->
            ruleSetProviders
                .filterNot { it is DefaultRuleSetProvider }

        is RulesSpec.RunPolicy.RestrictToSingleRule -> {
            val ruleSetId = runPolicy.ruleSetId
            val ruleId = runPolicy.ruleId
            val realProvider = requireNotNull(ruleSetProviders.find { it.ruleSetId == ruleSetId }) {
                "There was no rule set with id '$ruleSetId'."
            }
            val ruleName = requireNotNull(extractRuleName(ruleId)) {
                "There was not rule '$ruleId' in rule set '$ruleSetId'."
            }
            listOf(SingleRuleProvider(ruleName, realProvider))
        }
    }
        .also {
            debug {
                "Registered rule sets: $LIST_ITEM_SPACING" +
                    it.joinToString(LIST_ITEM_SPACING) { it.javaClass.canonicalName }
            }
        }
}
package dev.detekt.core.extensions

import dev.detekt.api.Extension
import dev.detekt.core.NL
import dev.detekt.core.ProcessingSettings
import java.util.ServiceLoader

val LIST_ITEM_SPACING = "$NL    "

inline fun <reified T : Extension> loadExtensions(
    settings: ProcessingSettings,
    predicate: (T) -> Boolean = { true },
): List<T> =
    ServiceLoader.load(T::class.java, settings.pluginLoader)
        .filterNot { it.id in settings.spec.extensionsSpec.disabledExtensions }
        .filter(predicate)
        .sortedByDescending { it.priority }
        .onEach {
            it.init(settings)
        }
        .also {
            settings.debug {
                "Loaded extensions: $LIST_ITEM_SPACING" +
                    it.joinToString(LIST_ITEM_SPACING) { it.javaClass.canonicalName }
            }
        }

